  // 하트 버튼 클릭 여부 추적을 위한 Set
  const processedComments = new Set();

  // 스크롤 다운 함수 (개선된 버전)
  async function advancedScrollDown() {
    const ironList = document.querySelector('tp-yt-iron-list');
    if (!ironList || !ironList.scrollToIndex) {
      console.error("⚠️ tp-yt-iron-list 또는 scrollToIndex 메소드 찾기 실패");
      return false;
    }

    const prevCount = ironList.items ? ironList.items.length : 0;
    ironList.scrollToIndex(prevCount - 1);

    // 새 댓글 로딩 대기 및 확인
    return new Promise((resolve) => {
      let attempts = 0;
      const maxAttempts = 5; // 최대 5번 시도

      const checkNewComments = () => {
        const currCount = ironList.items ? ironList.items.length : 0;

        if (currCount > prevCount) {
          console.log(`🔽 스크롤 성공: ${prevCount} -> ${currCount}`);
          resolve(true);
        } else {
          attempts++;

          if (attempts < maxAttempts) {
            console.log(`⏳ 새 댓글 로딩 대기 (${attempts}/${maxAttempts})`);
            setTimeout(checkNewComments, 2000);
          } else {
            console.log("⚠️ 새 댓글 로딩 실패");
            resolve(false);
          }
        }
      };

      // 초기 대기 후 확인 시작
      setTimeout(checkNewComments, 2000);
    });
  }

  // 화면에 처리할 댓글이 있는지 확인
  function getProcessableComments() {
    const allComments = document.querySelectorAll('ytcp-comment-thread');
    return Array.from(allComments).filter(comment => {
      // depth 속성이 0이거나 없는 댓글만 포함 (대댓글 제외)
      const depth = comment.getAttribute('depth');
      if (depth && depth !== "0") return false;

      // 이미 처리된 댓글 제외
      const commentText = comment.textContent.trim().slice(0, 100);
      if (processedComments.has(commentText)) return false;

      // 화면에 완전히 보이는지 확인 (조금이라도 잘리면 제외)
      const rect = comment.getBoundingClientRect();
      return (
        rect.top >= 0 && 
        rect.left >= 0 && 
        rect.bottom <= window.innerHeight && 
        rect.right <= window.innerWidth
      );
    });
  }

